"""Pure invoice validation and event sorting utilities.

This module contains 30 independent functions for validating invoice records
and sorting invoice/event data. All functions are pure: they do not mutate
their inputs and do not perform I/O. Records are expected to be mappings with
keys such as ``id``, ``account``, ``status``, ``qty``, ``unit_cents``, and
``note``.
"""

from __future__ import annotations

from typing import Any, Iterable, Mapping, Sequence


def validate_record_shape(record: Mapping[str, Any]) -> bool:
    """Return True if a record has the expected invoice keys."""
    required = {"id", "account", "status", "qty", "unit_cents", "note"}
    return isinstance(record, Mapping) and required.issubset(record.keys())


def validate_record_id(record: Mapping[str, Any]) -> bool:
    """Return True if the record id is a non-empty string."""
    value = record.get("id")
    return isinstance(value, str) and value.strip() != ""


def validate_account(record: Mapping[str, Any]) -> bool:
    """Return True if the account field is a non-empty string."""
    value = record.get("account")
    return isinstance(value, str) and value.strip() != ""


def validate_status(record: Mapping[str, Any]) -> bool:
    """Return True if status is one of the accepted invoice statuses."""
    value = record.get("status")
    return isinstance(value, str) and value.lower() in {"paid", "pending", "void", "refunded"}


def validate_quantity(record: Mapping[str, Any]) -> bool:
    """Return True if qty is a positive integer."""
    value = record.get("qty")
    return isinstance(value, int) and not isinstance(value, bool) and value > 0


def validate_unit_cents(record: Mapping[str, Any]) -> bool:
    """Return True if unit_cents is a non-negative integer."""
    value = record.get("unit_cents")
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def validate_note(record: Mapping[str, Any]) -> bool:
    """Return True if note is a string."""
    return isinstance(record.get("note"), str)


